CREATE TABLE public.account_onboarding (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, password_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_onboarding TO authenticated; GRANT ALL ON public.account_onboarding TO service_role;
ALTER TABLE public.account_onboarding ENABLE ROW LEVEL SECURITY;
CREATE POLICY onboarding_self_read ON public.account_onboarding FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_platform_admin());
CREATE TABLE public.ai_report_preferences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pharmacy_id uuid NOT NULL REFERENCES public.pharmacies(id) ON DELETE CASCADE, frequency text NOT NULL CHECK (frequency IN ('daily','weekly','monthly')), recipient_ids uuid[] NOT NULL DEFAULT '{}', topics text[] NOT NULL DEFAULT ARRAY['sales','expenses','stock','orders'], language text NOT NULL DEFAULT 'English' CHECK (language IN ('English','Swahili')), delivery_hour integer NOT NULL DEFAULT 8 CHECK (delivery_hour BETWEEN 0 AND 23), enabled boolean NOT NULL DEFAULT false, pause_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(pharmacy_id,frequency));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.ai_report_preferences TO authenticated; GRANT ALL ON public.ai_report_preferences TO service_role;
ALTER TABLE public.ai_report_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_owner_manage ON public.ai_report_preferences FOR ALL TO authenticated USING (public.is_platform_admin() OR public.is_pharmacy_owner(pharmacy_id)) WITH CHECK (public.is_platform_admin() OR (public.is_pharmacy_owner(pharmacy_id) AND public.pharmacy_is_current(pharmacy_id)));
CREATE TABLE public.ai_report_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), preference_id uuid NOT NULL REFERENCES public.ai_report_preferences(id) ON DELETE CASCADE, recipient_id uuid NOT NULL, period_key text NOT NULL, status text NOT NULL DEFAULT 'processing', summary text, error text, lease_until timestamptz NOT NULL DEFAULT now()+interval '10 minutes', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(preference_id,recipient_id,period_key));
GRANT SELECT ON public.ai_report_runs TO authenticated; GRANT ALL ON public.ai_report_runs TO service_role;
ALTER TABLE public.ai_report_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_owner_history ON public.ai_report_runs FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.ai_report_preferences p WHERE p.id=preference_id AND (public.is_platform_admin() OR public.is_pharmacy_owner(p.pharmacy_id))));
CREATE OR REPLACE FUNCTION public.touch_report_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER report_preferences_updated BEFORE UPDATE ON public.ai_report_preferences FOR EACH ROW EXECUTE FUNCTION public.touch_report_updated_at();
CREATE TRIGGER report_runs_updated BEFORE UPDATE ON public.ai_report_runs FOR EACH ROW EXECUTE FUNCTION public.touch_report_updated_at();
CREATE TRIGGER onboarding_updated BEFORE UPDATE ON public.account_onboarding FOR EACH ROW EXECUTE FUNCTION public.touch_report_updated_at();
CREATE TABLE public.ai_report_lock (id integer PRIMARY KEY CHECK(id=1), lease_until timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ai_report_lock TO service_role;
ALTER TABLE public.ai_report_lock ENABLE ROW LEVEL SECURITY;
INSERT INTO public.ai_report_lock(id) VALUES(1);
CREATE OR REPLACE FUNCTION public.acquire_ai_report_lock() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.ai_report_lock SET lease_until=now()+interval '10 minutes',updated_at=now() WHERE id=1 AND lease_until<now(); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.acquire_ai_report_lock() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.acquire_ai_report_lock() TO service_role;